-- The schema Hibernate's ddl-auto created before the migrations existed, dumped from a data
-- volume built by the last release that ran with ddl-auto=update. Enum-backed columns are native
-- ENUM here, which is exactly what a migrated deployment has to be able to start against.
CREATE CACHED TABLE "PUBLIC"."LEARNING"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "ACTION_DETAIL" CHARACTER LARGE OBJECT,
    "CONFIDENCE" FLOAT(53),
    "CREATED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "EVIDENCE" CHARACTER LARGE OBJECT,
    "FINGERPRINT" CHARACTER VARYING(64),
    "LAST_APPLIED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "LESSON" CHARACTER LARGE OBJECT NOT NULL,
    "RECOMMENDED_ACTION" ENUM('DEVIN_KNOWLEDGE', 'MEND_BACKLOG', 'PROMPT_PREAMBLE', 'REPO_INSTRUCTIONS', 'RETIRE'),
    "REPO" CHARACTER VARYING(255),
    "RETIRED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "RETIRED_BEFORE_PROMOTION" BOOLEAN DEFAULT FALSE NOT NULL,
    "SCOPE" ENUM('GENERAL', 'REPO') NOT NULL,
    "SOURCE_ISSUE" INTEGER,
    "SOURCE_PR_URL" CHARACTER VARYING(255),
    "SOURCE_REPO" CHARACTER VARYING(255),
    "STATUS" ENUM('ACTIVE', 'RETIRED') NOT NULL,
    "TIMES_APPLIED" INTEGER DEFAULT 0 NOT NULL,
    "TIMES_FOLLOWED_BY_FEEDBACK" INTEGER DEFAULT 0 NOT NULL,
    "TIMES_RETIRED" INTEGER DEFAULT 0 NOT NULL,
    "TOPIC" CHARACTER VARYING(64),
    "UPDATED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "VERSION" BIGINT
);
ALTER TABLE "PUBLIC"."LEARNING" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_8" PRIMARY KEY("ID");
CREATE INDEX "PUBLIC"."IDX_LEARNING_REPO" ON "PUBLIC"."LEARNING"("REPO" NULLS FIRST, "STATUS" NULLS FIRST);
CREATE CACHED TABLE "PUBLIC"."REMEDIATION_TASK"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "ACU_BUDGET" INTEGER,
    "ATTEMPTS" INTEGER NOT NULL,
    "CI_STATUS" CHARACTER VARYING(255),
    "COMPLETED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "CONFIDENCE" FLOAT(53),
    "CONTRACT_DISPATCHED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "CREATED_AT" TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    "CRITERIA_HASH" CHARACTER VARYING(255),
    "CRITERIA_JSON" CHARACTER LARGE OBJECT,
    "CRITERIA_SESSION_ID" CHARACTER VARYING(255),
    "CRITERIA_SESSION_URL" CHARACTER VARYING(255),
    "CRITERIA_STARTED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "DISPATCHED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "ETA_AT" TIMESTAMP(6) WITH TIME ZONE,
    "EXCLUSION_REASON" CHARACTER VARYING(2048),
    "FEEDBACK_JSON" CHARACTER LARGE OBJECT,
    "ISSUE_LABELS" CHARACTER VARYING(512),
    "ISSUE_NUMBER" INTEGER NOT NULL,
    "ISSUE_TITLE" CHARACTER VARYING(1024),
    "ISSUE_URL" CHARACTER VARYING(255),
    "LAST_ERROR" CHARACTER VARYING(2048),
    "LAST_NUDGED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "LAST_POLLED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "LAST_REVIEW_AT" TIMESTAMP(6) WITH TIME ZONE,
    "LEARNINGS_EXTRACTED" BOOLEAN DEFAULT FALSE NOT NULL,
    "LEASE_ACQUIRED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "LEASE_EXPIRES_AT" TIMESTAMP(6) WITH TIME ZONE,
    "LEASE_TAKEOVERS" INTEGER DEFAULT 0 NOT NULL,
    "NUDGES" INTEGER NOT NULL,
    "OUTCOME_JSON" CHARACTER LARGE OBJECT,
    "OWNER_ID" CHARACTER VARYING(128),
    "PR_OPENED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "PR_URL" CHARACTER VARYING(255),
    "READY_AT" TIMESTAMP(6) WITH TIME ZONE,
    "REPO" CHARACTER VARYING(255) NOT NULL,
    "RETROSPECTIVE_SESSION_ID" CHARACTER VARYING(255),
    "REVIEW_ROUNDS" INTEGER DEFAULT 0 NOT NULL,
    "SESSION_ID" CHARACTER VARYING(255),
    "SESSION_URL" CHARACTER VARYING(255),
    "STATE" ENUM('BLOCKED', 'CANCELLED', 'CHANGES_REQUESTED', 'CRITERIA_PENDING', 'DISCOVERED', 'DISPATCHED', 'FAILED', 'NEEDS_HUMAN', 'NOT_A_CANDIDATE', 'PR_OPEN', 'READY', 'RUNNING', 'SUCCEEDED', 'UNVERIFIED', 'VERIFYING') NOT NULL,
    "UPDATED_AT" TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    "VERIFICATION_JSON" CHARACTER LARGE OBJECT,
    "VERIFICATION_TIER" ENUM('CONTRACT_WORKFLOW', 'NONE', 'REPO_CI', 'VERIFIER_SESSION'),
    "VERIFIER_SESSION_ID" CHARACTER VARYING(255),
    "VERIFIER_SESSION_URL" CHARACTER VARYING(255),
    "VERSION" BIGINT
);
ALTER TABLE "PUBLIC"."REMEDIATION_TASK" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_5" PRIMARY KEY("ID");
CREATE INDEX "PUBLIC"."IDX_TASK_STATE" ON "PUBLIC"."REMEDIATION_TASK"("STATE" NULLS FIRST);
CREATE CACHED TABLE "PUBLIC"."REPOSITORY"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 2) NOT NULL,
    "ACCESS_CHECKED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "ACCESS_ERROR" CHARACTER VARYING(1024),
    "ACCESS_STATE" ENUM('MISSING_PERMISSION', 'NO_ACCESS', 'PENDING', 'VALIDATED') NOT NULL,
    "ACU_BUDGET" INTEGER,
    "COMMITS_SINCE_INDEX" INTEGER DEFAULT 0 NOT NULL,
    "CONTEXT_SESSION_ID" CHARACTER VARYING(128),
    "CONTEXT_SESSION_URL" CHARACTER VARYING(512),
    "CREATED_AT" TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    "DEFAULT_BRANCH" CHARACTER VARYING(128),
    "ENABLED" BOOLEAN DEFAULT TRUE NOT NULL,
    "INDEX_ERROR" CHARACTER VARYING(1024),
    "INDEX_STATE" ENUM('INDEXED', 'INDEXING', 'INDEX_FAILED', 'NEVER_INDEXED', 'STALE') NOT NULL,
    "INDEXED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "INDEXED_SHA" CHARACTER VARYING(64),
    "INSTALLATION_ID" CHARACTER VARYING(64),
    "NAME" CHARACTER VARYING(128) NOT NULL,
    "OWNER" CHARACTER VARYING(128) NOT NULL,
    "TRIGGER_LABEL" CHARACTER VARYING(128),
    "UPDATED_AT" TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    "VERSION" BIGINT
);
ALTER TABLE "PUBLIC"."REPOSITORY" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_9" PRIMARY KEY("ID");
CREATE CACHED TABLE "PUBLIC"."REPOSITORY_CONTEXT"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "CONTENT" CHARACTER LARGE OBJECT NOT NULL,
    "KIND" ENUM('AGENT_RULES', 'CI', 'COMMANDS', 'LAYOUT', 'PR_CONVENTIONS', 'RISK', 'STACK', 'TESTS') NOT NULL,
    "REPOSITORY_ID" BIGINT NOT NULL,
    "SOURCE_SHA" CHARACTER VARYING(64),
    "STALE" BOOLEAN DEFAULT FALSE NOT NULL,
    "UPDATED_AT" TIMESTAMP(6) WITH TIME ZONE NOT NULL
);
ALTER TABLE "PUBLIC"."REPOSITORY_CONTEXT" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_5F" PRIMARY KEY("ID");
CREATE INDEX "PUBLIC"."IDX_CONTEXT_REPO" ON "PUBLIC"."REPOSITORY_CONTEXT"("REPOSITORY_ID" NULLS FIRST);
CREATE CACHED TABLE "PUBLIC"."TASK_EVENT"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "ACTOR" CHARACTER VARYING(32) NOT NULL,
    "FROM_STATE" ENUM('BLOCKED', 'CANCELLED', 'CHANGES_REQUESTED', 'CRITERIA_PENDING', 'DISCOVERED', 'DISPATCHED', 'FAILED', 'NEEDS_HUMAN', 'NOT_A_CANDIDATE', 'PR_OPEN', 'READY', 'RUNNING', 'SUCCEEDED', 'UNVERIFIED', 'VERIFYING'),
    "OCCURRED_AT" TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    "REASON" CHARACTER VARYING(2048),
    "TASK_ID" BIGINT NOT NULL,
    "TASK_KEY" CHARACTER VARYING(255) NOT NULL,
    "TO_STATE" ENUM('BLOCKED', 'CANCELLED', 'CHANGES_REQUESTED', 'CRITERIA_PENDING', 'DISCOVERED', 'DISPATCHED', 'FAILED', 'NEEDS_HUMAN', 'NOT_A_CANDIDATE', 'PR_OPEN', 'READY', 'RUNNING', 'SUCCEEDED', 'UNVERIFIED', 'VERIFYING') NOT NULL
);
ALTER TABLE "PUBLIC"."TASK_EVENT" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_A" PRIMARY KEY("ID");
CREATE INDEX "PUBLIC"."IDX_EVENT_TASK" ON "PUBLIC"."TASK_EVENT"("TASK_ID" NULLS FIRST);
ALTER TABLE "PUBLIC"."REPOSITORY_CONTEXT" ADD CONSTRAINT "PUBLIC"."UKIOXPS7NQDBK1LUYM44XPG43G3" UNIQUE("REPOSITORY_ID", "KIND");
ALTER TABLE "PUBLIC"."LEARNING" ADD CONSTRAINT "PUBLIC"."UK1P7KXVWIFY5U5JM23KBWX2MI8" UNIQUE("FINGERPRINT");
ALTER TABLE "PUBLIC"."REPOSITORY" ADD CONSTRAINT "PUBLIC"."UK95FNGNI7F8714WAQ7UFNYH8P" UNIQUE("OWNER", "NAME");
ALTER TABLE "PUBLIC"."REMEDIATION_TASK" ADD CONSTRAINT "PUBLIC"."UKPB4HELJX754I9I6BVRJT1EMIL" UNIQUE("REPO", "ISSUE_NUMBER");
